package com.transportlogistics.app.tracking.domain.routedeviation;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.math.BigInteger;import java.util.*;import org.junit.jupiter.api.Test;
class RouteGeometryTest {
 private static RoutePoint p(double lon,double lat){return new RoutePoint(BigDecimal.valueOf(lon),BigDecimal.valueOf(lat));}
 @Test void validatesVersionAndGeometry(){assertEquals(BigInteger.valueOf(27),new RouteVersion("REVISION:27").revision());assertEquals(new BigInteger("999999999999999999999"),new RouteVersion("REVISION:999999999999999999999").revision());assertThrows(RouteDeviationException.class,()->new RouteVersion("LATEST"));assertThrows(RouteDeviationException.class,()->RouteVersion.ofRevision(0));assertThrows(RouteDeviationException.class,()->new RoutePolyline(new RouteVersion("REVISION:1"),List.of(p(0,0))));assertThrows(RouteDeviationException.class,()->new RoutePolyline(new RouteVersion("REVISION:1"),List.of(p(179.9,0),p(-179.9,0))));}
 @Test void calculatesPointToPolylineAndEndpoints(){RoutePolyline line=new RoutePolyline(new RouteVersion("REVISION:1"),List.of(p(0,0),p(.1,0)));assertEquals(0d,RouteDistanceCalculator.minimumDistance(p(.05,0),line).value().doubleValue(),.0001);assertEquals(1111.9,RouteDistanceCalculator.minimumDistance(p(.05,.01),line).value().doubleValue(),2);assertTrue(RouteDistanceCalculator.minimumDistance(p(-.01,0),line).value().doubleValue()>1100);}
 @Test void enforcesSegmentLimitAndAdjacentUniqueness(){assertThrows(RouteDeviationException.class,()->new RoutePolyline(new RouteVersion("REVISION:1"),List.of(p(0,0),p(0,0))));assertThrows(RouteDeviationException.class,()->new RoutePolyline(new RouteVersion("REVISION:1"),List.of(p(0,0),p(.3,0))));assertDoesNotThrow(()->new RoutePolyline(new RouteVersion("REVISION:1"),List.of(p(0,0),p(.224,0))));}
}
